import { Ionicons } from "@expo/vector-icons";
import type { CategoryDto } from "@amiyo/contracts";
import { useMemo, useState } from "react";
import { Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from "react-native";
import { colors, radius, spacing } from "../../../ui/tokens";

export function ProductCategorySelect({ categories, onChange, value }: { categories: CategoryDto[]; onChange(id: string): void; value: string }) {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState("");
  const selected = categories.find((item) => item.id === value);
  const paths = useMemo(() => buildPaths(categories), [categories]);
  const visible = paths.filter((item) => `${item.category.name} ${item.path}`.toLowerCase().includes(search.trim().toLowerCase()));
  const close = () => { setOpen(false); setSearch(""); };
  return <View style={styles.field}><Text style={styles.label}>Category *</Text><Pressable onPress={() => setOpen(true)} style={styles.select}><Text numberOfLines={1} style={[styles.value, !selected && styles.placeholder]}>{selected ? paths.find((item) => item.category.id === selected.id)?.path : "Select product category"}</Text><Ionicons color={colors.muted} name="chevron-down" size={18} /></Pressable><Modal animationType="fade" onRequestClose={close} transparent visible={open}><Pressable onPress={close} style={styles.backdrop}><Pressable onPress={() => undefined} style={styles.modal}><View style={styles.header}><View><Text style={styles.eyebrow}>PRODUCT PLACEMENT</Text><Text style={styles.title}>Select category</Text></View><Pressable onPress={close} style={styles.close}><Ionicons color={colors.text} name="close" size={20} /></Pressable></View><View style={styles.search}><Ionicons color={colors.muted} name="search-outline" size={18} /><TextInput autoFocus onChangeText={setSearch} placeholder="Search categories" placeholderTextColor={colors.muted} style={styles.searchInput} value={search} /></View><ScrollView keyboardShouldPersistTaps="handled" style={styles.list}>{visible.map((item) => { const active = item.category.id === value; return <Pressable key={item.category.id} onPress={() => { onChange(item.category.id); close(); }} style={[styles.option, active && styles.optionActive]}><View style={styles.optionCopy}><Text style={[styles.optionName, active && styles.optionNameActive]}>{item.category.name}</Text><Text numberOfLines={1} style={styles.path}>{item.path}</Text></View>{active ? <Ionicons color={colors.primary} name="checkmark-circle" size={20} /> : null}</Pressable>; })}</ScrollView></Pressable></Pressable></Modal></View>;
}

function buildPaths(categories: CategoryDto[]) { const byId = new Map(categories.map((item) => [item.id, item])); return categories.map((category) => { const names = [category.name]; const seen = new Set([category.id]); let parentId = category.parentId; while (parentId && !seen.has(parentId)) { const parent = byId.get(parentId); if (!parent) break; names.unshift(parent.name); seen.add(parent.id); parentId = parent.parentId; } return { category, path: names.join(" › ") }; }).sort((left, right) => left.path.localeCompare(right.path)); }
const styles = StyleSheet.create({ field: { gap: 6 }, label: { color: colors.text, fontSize: 12, fontWeight: "800" }, select: { alignItems: "center", backgroundColor: "#f8fafc", borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, flexDirection: "row", minHeight: 48, paddingHorizontal: 13 }, value: { color: colors.text, flex: 1 }, placeholder: { color: colors.muted }, backdrop: { alignItems: "center", backgroundColor: "rgba(15,23,42,.5)", flex: 1, justifyContent: "center", padding: spacing.md }, modal: { backgroundColor: colors.surface, borderRadius: radius.xl, maxHeight: "82%", maxWidth: 620, padding: spacing.lg, width: "100%" }, header: { alignItems: "center", flexDirection: "row", justifyContent: "space-between" }, eyebrow: { color: colors.primary, fontSize: 9, fontWeight: "900", letterSpacing: 1 }, title: { color: colors.text, fontSize: 22, fontWeight: "900", marginTop: 3 }, close: { alignItems: "center", backgroundColor: "#f1f5f9", borderRadius: radius.pill, height: 38, justifyContent: "center", width: 38 }, search: { alignItems: "center", borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, flexDirection: "row", gap: 8, marginTop: spacing.md, paddingHorizontal: 12 }, searchInput: { color: colors.text, flex: 1, minHeight: 46, outlineStyle: "none" } as never, list: { marginTop: spacing.sm }, option: { alignItems: "center", borderBottomColor: colors.border, borderBottomWidth: 1, flexDirection: "row", minHeight: 56, paddingHorizontal: 10 }, optionActive: { backgroundColor: colors.primarySoft, borderRadius: radius.md }, optionCopy: { flex: 1 }, optionName: { color: colors.text, fontWeight: "800" }, optionNameActive: { color: colors.primary }, path: { color: colors.muted, fontSize: 9, marginTop: 3 } });
